"""Build the storm-surge review player from the current local timeline."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parent;D=ROOT/'integrated';s=json.loads((D/'shot.json').read_text())
css='*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#171512;font:17px/1.5 system-ui,sans-serif}.wrap{max-width:1080px;margin:auto;padding:20px}a{color:inherit}h1{font-size:clamp(32px,7vw,62px);line-height:1.05;margin:22px 0 12px}nav{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}.meta{font-size:14px;color:#625b50}.badge{display:inline-block;background:#ef9f3a;padding:4px 9px;font-size:12px;font-weight:700}.player{background:#fffdf7;border:1px solid #d5caba;border-radius:8px;overflow:hidden}video{display:block;width:100%;max-height:65vh;background:#fffdf7}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}button{font:inherit;border:1px solid #aaa18f;background:#fffdf7;color:#171512;border-radius:5px;padding:9px 14px;cursor:pointer}button[aria-pressed=true]{background:#171512;color:#fffdf7}.keys{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;border:1px solid #d5caba;background:#fffdf7;border-radius:6px;overflow:hidden}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.pair img{width:100%;display:block}figcaption{padding:10px;font-size:13px}summary{cursor:pointer}details{margin:22px 0}footer{margin:28px 0;border-top:1px solid #d5caba;padding-top:16px;font-size:14px}@media(max-width:600px){.keys{grid-template-columns:1fr}.wrap{padding:14px}button{font-size:15px}}'
script="const v=document.querySelector('#film');for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{const t=v.currentTime;const playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(t,v.duration||0);if(playing)v.play().catch(()=>{})},{once:true});v.load()});"
cards=''.join(f'<figure><div class="pair"><img src="source-{k:02d}.jpg" alt="Source at {s["frames"][f]["source_time"]:.3f} seconds"><img src="key-{k:02d}.png" alt="Assembled key {k}"></div><figcaption>Key {k} · source {s["frames"][f]["source_time"]:.3f} s</figcaption></figure>' for k,f in enumerate(s['keys'],1))
reviews=' · '.join(f'<a href="{p.name}">{escape(p.stem)}</a>' for p in sorted(D.glob('review-v*.json'))) or 'Independent review pending.'
badge=s.get('review_badge','ASSEMBLED REVIEW COPY')
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Storm surge · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>{css}</style><body><main class="wrap"><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../wave2-keyframes.html">All ten subjects</a><a href="../index.html">Earlier keys</a></nav><h1>Storm surge at the building.</h1><p class="meta">{s['frame_count']} rendered frames · {s['fps']} fps · {len(s['keys'])} integrated keys · {s['duration']:.3f} seconds</p><p><span class="badge">{escape(badge)}</span></p><div class="player"><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video></div><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Cartoon</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Source beside cartoon</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Source</button></div><p class="meta">{escape(s['assembly_summary'])}</p><p class="meta">{escape(s['review_note'])}</p><h2>Eight moments, fully assembled.</h2><p class="meta">Source at left, assembled cartoon at right.</p><section class="keys">{cards}</section><details><summary>References and review</summary><p>Quick, Draw! key {s['design']['key_id']}, all seven original strokes. Quick, Draw! contributors / Google Creative Lab, CC BY 4.0. The building and occluding water boundary were drawn by agent against the source; the glyph is an abstraction of water.</p><p>Archive: <a href="{escape(s['source']['page_url'])}">{escape(s['source']['source_title'])}</a> ({escape(s['source']['source_year'])}), clip-relative 31.131–34.201 seconds. Reported archive rights were absent from the candidate manifest.</p><p><a href="shot.json">Timeline</a> · <a href="correspondence.json">Crest keys and correspondence</a> · <a href="camera.json">Measured camera translation</a> · <a href="assembly-checks.json">Assembly checks</a> · {reviews}</p><p>SAM2.1 ran upstream, but its mask switches from water to the building; a persistent single-object fit is not established. Recognition and normal-speed playback approval remain unrun. Camera alignment is 2D translation and the bounded foam texture drift is not tracked physical water particles. No training ran.</p><p><a href="sam/provenance.json">SAM provenance</a> · <a href="traced.json">Character trace</a> · <a href="design.png">Original doodle</a></p></details><footer><a href="cartoon.mp4" download>Download cartoon</a> · <a href="comparison.mp4" download>Download synchronized comparison</a></footer></main><script>{script}</script></html>'''
(D/'index.html').write_text(page)
print(D/'index.html')
